/**
 * moire-dm's two inputs from disk, both parsed strictly and failing closed:
 *
 * - The daemon configuration (/etc/moire-dm/config.json), generated by Nix into the read-only
 *   store: VT, session PATH, the greeter and front accounts, the greeter command, and the
 *   session catalog. The greeter picks a session by catalog id; it never supplies a command.
 * - Automatic login state (/var/lib/moire-dm/autologin.json), the one runtime-editable
 *   setting. Anything unexpected about it (owner, mode, size, shape, unknown session) means
 *   "no automatic login", never a guess.
 */
import { validSession, type SessionSpec } from "./worker-channel";

export type DmConfig = Readonly<{
  vt: number;
  /** The front's greeter socket, handed to the greeter as MOIRE_DM_SOCK. */
  socket: string;
  /** The unprivileged account the front (the only reader of greeter bytes) runs as. */
  frontUser: string;
  path: string;
  greeter: Readonly<{ user: string; argv: readonly [string, ...string[]] }>;
  sessions: readonly SessionSpec[];
}>;

export type Autologin =
  | Readonly<{ kind: "disabled" }>
  | Readonly<{ kind: "enabled"; user: string; session: SessionSpec }>
  | Readonly<{ kind: "invalid"; reason: AutologinProblem }>;

export type AutologinProblem = "owner" | "mode" | "size" | "shape" | "user" | "session";

/** What the daemon learns from lstat() of the autologin file, so the policy stays pure. */
export type FileFacts = Readonly<{
  regularFile: boolean;
  ownerUid: number;
  mode: number;
  size: number;
}>;

const MAX_AUTOLOGIN_BYTES = 4096;
const AUTOLOGIN_VERSION = 1;
/** sun_path is 108 bytes including the terminator. */
const MAX_SOCKET_PATH_BYTES = 107;
/** Group- or world-writable state could be rewritten by someone other than its writer. */
const WRITABLE_BY_OTHERS = 0o022;
/** Same syntax systemd accepts for strict user names (and the greeter's own check). */
const ACCOUNT_NAME = /^[a-z_][a-z0-9_-]{0,30}\$?$/;

/** Regular accounts only; system accounts (and root) never get a user session. */
export const MIN_USER_UID = 1000;

export function validAccountName(name: string): boolean {
  return ACCOUNT_NAME.test(name);
}

function record(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

export function parseConfig(text: string): DmConfig | null {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return null;
  }
  const config = record(raw);
  const greeter = record(config?.greeter);
  if (
    !config ||
    !greeter ||
    !Number.isSafeInteger(config.vt) ||
    (config.vt as number) < 1 ||
    (config.vt as number) > 63 ||
    typeof config.path !== "string" ||
    typeof config.socket !== "string" ||
    !config.socket.startsWith("/") ||
    Buffer.byteLength(config.socket) > MAX_SOCKET_PATH_BYTES ||
    typeof greeter.user !== "string" ||
    !validAccountName(greeter.user) ||
    !validSession({
      id: "greeter",
      label: "Greeter",
      desktop: "moire-greeter",
      argv: greeter.argv,
    }) ||
    typeof config.frontUser !== "string" ||
    !validAccountName(config.frontUser) ||
    config.frontUser === greeter.user ||
    !Array.isArray(config.sessions) ||
    config.sessions.length < 1 ||
    !config.sessions.every(validSession)
  )
    return null;
  const sessions = config.sessions as SessionSpec[];
  if (new Set(sessions.map((session) => session.id)).size !== sessions.length) return null;
  return {
    vt: config.vt as number,
    socket: config.socket,
    frontUser: config.frontUser,
    path: config.path,
    greeter: { user: greeter.user, argv: greeter.argv as [string, ...string[]] },
    sessions,
  };
}

/** The catalog entry the greeter picked by id. */
export function sessionById(config: DmConfig, id: string): SessionSpec | null {
  return config.sessions.find((session) => session.id === id) ?? null;
}

/**
 * `writerUid` is the account allowed to own the file: root, or the unprivileged settings
 * writer proposed in docs/moire-dm.md.
 */
export function parseAutologin(
  config: DmConfig,
  facts: FileFacts | null,
  text: string | null,
  writerUid: number,
): Autologin {
  if (!facts || text === null) return { kind: "disabled" };
  if (!facts.regularFile || (facts.ownerUid !== 0 && facts.ownerUid !== writerUid))
    return { kind: "invalid", reason: "owner" };
  if ((facts.mode & WRITABLE_BY_OTHERS) !== 0) return { kind: "invalid", reason: "mode" };
  if (facts.size > MAX_AUTOLOGIN_BYTES || text.length > MAX_AUTOLOGIN_BYTES)
    return { kind: "invalid", reason: "size" };
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return { kind: "invalid", reason: "shape" };
  }
  const state = record(raw);
  if (!state || state.version !== AUTOLOGIN_VERSION) return { kind: "invalid", reason: "shape" };
  if (state.user === null && Object.keys(state).length === 2) return { kind: "disabled" };
  if (Object.keys(state).length !== 3 || typeof state.session !== "string")
    return { kind: "invalid", reason: "shape" };
  if (typeof state.user !== "string" || !validAccountName(state.user))
    return { kind: "invalid", reason: "user" };
  if (state.user === config.greeter.user) return { kind: "invalid", reason: "user" };
  const session = config.sessions.find((entry) => entry.id === state.session);
  if (!session) return { kind: "invalid", reason: "session" };
  return { kind: "enabled", user: state.user, session };
}
